"use client";

import { animate, motion, useMotionValue, useReducedMotion, type HTMLMotionProps, type Transition } from "motion/react";
import { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a magnetic button. Every length is in CSS pixels. */
export type MagneticButtonProps = Omit<HTMLMotionProps<"button">, "style"> & {
  /** How far outside its own edge the button starts to notice the pointer. */
  reach?: number;
  /** The share of the pointer's distance from the centre that the button follows, from 0 to 1. */
  strength?: number;
  /** The most the button moves on either axis. Keep it under 8, the margin its hit area grows by. */
  maxTravel?: number;
  /** Tells the caller when the button starts or stops leaning. */
  onLeanChange?: (leaning: boolean) => void;
};

// Critically damped (2 × √300 ≈ 34.6): the button follows the pointer and settles home with no wobble.
const LEAN: Transition = { type: "spring", stiffness: 300, damping: 35, mass: 1 };

const clamp = (value: number, limit: number) => Math.min(limit, Math.max(-limit, value));

/**
 * A call-to-action button that leans a few pixels toward a nearby mouse
 * pointer and settles back when the pointer leaves. Touch, pen and keyboard
 * focus never move it.
 */
export function MagneticButton({
  reach = 40,
  strength = 0.3,
  maxTravel = 6,
  onLeanChange,
  className,
  disabled,
  type = "button",
  onFocus,
  onBlur,
  ...buttonProps
}: MagneticButtonProps) {
  const ref = useRef<HTMLButtonElement>(null);
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const [leaning, setLeaning] = useState(false);
  const leaningRef = useRef(false);
  const keyboardFocus = useRef(false);
  const reduceMotion = useReducedMotion();
  const onLeanChangeRef = useRef(onLeanChange);
  useEffect(() => {
    onLeanChangeRef.current = onLeanChange;
  }, [onLeanChange]);

  const still = Boolean(reduceMotion || disabled);

  useEffect(() => {
    const lean = (toX: number, toY: number) => {
      animate(x, toX, LEAN);
      animate(y, toY, LEAN);
      const next = toX !== 0 || toY !== 0;
      if (next === leaningRef.current) return;
      leaningRef.current = next;
      setLeaning(next);
      onLeanChangeRef.current?.(next);
    };

    if (still) {
      lean(0, 0);
      return;
    }

    const follow = (event: PointerEvent) => {
      const button = ref.current;
      // Only a mouse can sit near a button without pressing it.
      if (!button || event.pointerType !== "mouse" || keyboardFocus.current) return;
      const rect = button.getBoundingClientRect();
      // Take the lean back out, so the button measures from its resting place and cannot chase itself.
      const centreX = rect.left - x.get() + rect.width / 2;
      const centreY = rect.top - y.get() + rect.height / 2;
      const dx = event.clientX - centreX;
      const dy = event.clientY - centreY;
      const near = Math.abs(dx) <= rect.width / 2 + reach && Math.abs(dy) <= rect.height / 2 + reach;
      if (near) lean(clamp(dx * strength, maxTravel), clamp(dy * strength, maxTravel));
      else lean(0, 0);
    };
    const home = () => lean(0, 0);

    const controller = new AbortController();
    window.addEventListener("pointermove", follow, { signal: controller.signal, passive: true });
    // The pointer can leave the page without one last move event.
    document.documentElement.addEventListener("pointerleave", home, { signal: controller.signal });
    window.addEventListener("blur", home, { signal: controller.signal });
    return () => controller.abort();
  }, [maxTravel, reach, still, strength, x, y]);

  return (
    <motion.button
      {...buttonProps}
      ref={ref}
      type={type}
      disabled={disabled}
      data-leaning={leaning}
      style={{ x, y }}
      whileTap={still ? undefined : { scale: 0.97 }}
      onFocus={(event) => {
        onFocus?.(event);
        // A focus ring that drifts is hard to track, so keyboard focus sends the button home.
        let visible = false;
        try {
          visible = event.currentTarget.matches(":focus-visible");
        } catch {
          visible = false;
        }
        keyboardFocus.current = visible;
        if (!visible) return;
        animate(x, 0, LEAN);
        animate(y, 0, LEAN);
        if (!leaningRef.current) return;
        leaningRef.current = false;
        setLeaning(false);
        onLeanChange?.(false);
      }}
      onBlur={(event) => {
        onBlur?.(event);
        keyboardFocus.current = false;
      }}
      className={cn(
        // No `transition` on transform here: a CSS transition would lag the spring that drives it.
        "relative inline-flex min-h-11 cursor-pointer touch-manipulation items-center justify-center gap-2 rounded-full bg-primary px-6 text-sm font-medium text-primary-foreground outline-none",
        // The hit area reaches 8px past every edge, more than the button can travel.
        "before:absolute before:-inset-2 before:rounded-full",
        "motion-safe:transition-colors motion-safe:duration-150",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-50",
        className,
      )}
    />
  );
}
